css:
.crossborder-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2530;
    background: linear-gradient(165deg, #f4f6fa 0%, #eef1f7 55%, #e9edf4 100%);
    border-radius: 18px;
}

.crossborder-container * {
    box-sizing: border-box;
}

.crossborder-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #0c1f3f 0%, #173a63 55%, #1f5a72 100%);
    color: #f3f7fc;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(12, 31, 63, 0.32);
}

.crossborder-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.crossborder-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e9c884;
    background: rgba(233, 200, 132, 0.12);
    border: 1px solid rgba(233, 200, 132, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.crossborder-subtitle {
    margin: 0 auto;
    max-width: 850px;
    font-size: 1rem;
    line-height: 1.58;
    color: #cdd9e8;
}

.crossborder-partners {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.crossborder-partner {
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 16px;
    box-shadow: 0 4px 14px rgba(28, 37, 48, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-top: 4px solid #173a63;
}

.crossborder-partner-us { border-top-color: #b23b3b; }
.crossborder-partner-sg { border-top-color: #1f8a76; }
.crossborder-partner-br { border-top-color: #d99020; }
.crossborder-partner-lu { border-top-color: #7d5fc0; }

.crossborder-partner-name {
    font-weight: 800;
    font-size: 0.98rem;
    color: #0c1f3f;
}

.crossborder-partner-us .crossborder-partner-name { color: #a13232; }
.crossborder-partner-sg .crossborder-partner-name { color: #157561; }
.crossborder-partner-br .crossborder-partner-name { color: #b3771a; }
.crossborder-partner-lu .crossborder-partner-name { color: #6849b0; }

.crossborder-partner-meta {
    font-size: 0.78rem;
    color: #5f6f80;
    line-height: 1.4;
}

.crossborder-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #45586a;
    margin-bottom: 16px;
    padding: 4px;
}

.crossborder-period-counter #currentDay,
.crossborder-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f5a72;
}

.crossborder-round-name {
    background: rgba(31, 90, 114, 0.13);
    color: #195062;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.crossborder-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8801f;
    background: rgba(217, 144, 32, 0.14);
    border: 1px solid rgba(217, 144, 32, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.crossborder-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.crossborder-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.08);
    border-top: 4px solid #173a63;
}

.crossborder-card-budget { border-top-color: #173a63; }
.crossborder-card-enrol { border-top-color: #1f8a76; }
.crossborder-card-align { border-top-color: #d99020; }
.crossborder-card-core { border-top-color: #7d5fc0; }

.crossborder-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7c8d;
}

.crossborder-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.08;
    margin: 4px 0 2px;
    color: #0c1f3f;
    font-variant-numeric: tabular-nums;
}

.crossborder-card-budget .crossborder-value { color: #173a63; }
.crossborder-card-enrol .crossborder-value { color: #1f8a76; }
.crossborder-card-align .crossborder-value { color: #b3771a; }
.crossborder-card-core .crossborder-value { color: #6849b0; }

.crossborder-sublabel {
    font-size: 0.75rem;
    color: #76889a;
    line-height: 1.35;
}

.crossborder-card-budget.crossborder-budget-over { border-top-color: #c0392b; }
.crossborder-card-budget.crossborder-budget-over .crossborder-value { color: #c0392b; }

.crossborder-card-enrol.crossborder-enrol-good { border-top-color: #1f8a76; }
.crossborder-card-enrol.crossborder-enrol-good .crossborder-value { color: #1f8a76; }
.crossborder-card-enrol.crossborder-enrol-bad { border-top-color: #c0392b; }
.crossborder-card-enrol.crossborder-enrol-bad .crossborder-value { color: #c0392b; }

.crossborder-card-core.crossborder-core-bad { border-top-color: #c0392b; }
.crossborder-card-core.crossborder-core-bad .crossborder-value { color: #c0392b; }

.crossborder-cps-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde4ec;
    color: #45586a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.crossborder-cps-bar #cpsDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #173a63;
    font-weight: 800;
}

.crossborder-cps-bar.crossborder-cps-good #cpsDisplay { color: #1f8a76; }
.crossborder-cps-bar.crossborder-cps-bad #cpsDisplay { color: #c0392b; }

.crossborder-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1f5a72;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.07);
}

.crossborder-briefing-icon {
    font-size: 1.85rem;
    line-height: 1;
}

.crossborder-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #0c1f3f;
    margin-bottom: 6px;
}

.crossborder-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #3a4b5c;
}

.crossborder-briefing-text strong { color: #1f5a72; }
.crossborder-briefing-text em { color: #b3771a; font-style: italic; }

.crossborder-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.07);
}

.crossborder-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0c1f3f;
    border-bottom: 2px solid #e6ebf1;
    padding-bottom: 8px;
}

.crossborder-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3b4c;
    margin: 14px 0 6px;
}

.crossborder-container select,
.crossborder-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d1da;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1c2530;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.crossborder-container select:focus,
.crossborder-container input[type="number"]:focus {
    outline: none;
    border-color: #1f5a72;
    box-shadow: 0 0 0 3px rgba(31, 90, 114, 0.16);
}

.crossborder-container select option {
    background-color: #ffffff;
    color: #1c2530;
}

.crossborder-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f5a72;
}

.crossborder-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #45586a;
    margin-top: 4px;
}

.crossborder-range-readout span:nth-child(2) {
    color: #1f5a72;
    font-weight: 800;
}

.crossborder-hint {
    font-size: 0.8rem;
    color: #76889a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.crossborder-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.crossborder-container .btn-primary {
    background: linear-gradient(135deg, #173a63 0%, #1f5a72 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(23, 58, 99, 0.32);
}

.crossborder-container .btn-primary:hover {
    filter: brightness(1.08);
}

.crossborder-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d1da;
    color: #5f6f80;
    background: transparent;
}

.crossborder-coach {
    background: linear-gradient(160deg, #0c1f3f 0%, #142e52 100%);
    color: #e1ebf5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(12, 31, 63, 0.26);
}

.crossborder-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e9c884;
    margin-bottom: 8px;
}

.crossborder-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.crossborder-coach-body strong { color: #7fc9e0; }
.crossborder-coach-body em { color: #e9c884; font-style: italic; }

.crossborder-history,
.crossborder-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.07);
}

.crossborder-history h3,
.crossborder-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0c1f3f;
}

.crossborder-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4b5c;
}

.crossborder-container table#usfHistoryTable th {
    background: #eef2f7;
    color: #1f5a72;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d7e0ea;
}

.crossborder-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f5;
    color: #3a4b5c;
}

.crossborder-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fc;
}

.crossborder-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .crossborder-container {
        padding: 14px;
    }
    .crossborder-header h1 {
        font-size: 1.8rem;
    }
    .crossborder-partners {
        grid-template-columns: repeat(2, 1fr);
    }
    .crossborder-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .crossborder-value {
        font-size: 2.1rem;
    }
    .crossborder-clock {
        margin-left: 0;
    }
    .crossborder-period-counter {
        font-size: 0.88rem;
    }
    .crossborder-cps-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .crossborder-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (cbp- prefix; cross-border teal theme) ---- */
.cbp-completion { padding: 8px 4px 4px; }
.cbp-cm-head { text-align: center; margin-bottom: 16px; }
.cbp-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f8a76; }
.cbp-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #76889a; }
.cbp-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #14322c; }
.cbp-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.cbp-cm-yes { background: rgba(31,138,118,0.14); color: #1f8a76; border: 1px solid rgba(31,138,118,0.45); }
.cbp-cm-mid { background: rgba(118,136,154,0.14); color: #5f7286; border: 1px solid rgba(118,136,154,0.42); }
.cbp-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.cbp-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.cbp-cm-metric { flex: 1 1 100px; min-width: 92px; background: rgba(31,138,118,0.07); border: 1px solid rgba(31,138,118,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.cbp-cm-mv { display: block; font-size: 1.15rem; font-weight: 800; color: #1f8a76; }
.cbp-cm-ml { display: block; font-size: 0.66rem; margin-top: 4px; color: #76889a; text-transform: uppercase; letter-spacing: 0.03em; }
.cbp-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14322c; }
.cbp-cm-insights { margin: 0; padding-left: 20px; }
.cbp-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3a4a52; }

