(function() {
    'use strict';

    class CrossBorderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Cross-Border Program`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Atlantique Business School). ----
            this.BUDGET_CAP = 1200;        // EUR 1.2M design-and-launch budget, in €K
            this.TUITION = 32;             // EUR 32,000 tuition per executive, in €K
            this.BREAK_EVEN = 45;          // 45 paying executives to break even
            this.ENROL_FLOOR = 30;         // analyst range bottom
            this.ENROL_CEIL = 60;          // analyst range top
            this.US_SHARE = 9;             // Keystone (US) revenue share €9,000/student, in €K
            this.BRAZIL_AT_RISK = 740;     // EUR 740K committed spend sunk if Brazil accreditation rejected, in €K
            this.START_ENROL = 38;
            this.START_ALIGN = 52;
            this.START_CORE = 80;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 0,            // €K committed of the 1.2M envelope
                    enrol: this.START_ENROL, // projected paying executives
                    align: this.START_ALIGN, // cultural-alignment score (0–100)
                    core: this.START_CORE,   // competitive-core protection (0–100)
                    usShareCost: 0,       // €K/yr revenue share owed to the US partner at break-even
                    enrolTarget: this.BREAK_EVEN, // enrolment the P&L is built to break even on
                    // ---- Sticky, run-defining penalty flags (set when an error is committed). ----
                    brandTrap: false,        // chased US prestige without modelling its share against break-even
                    boundaryCeded: false,    // ceded the coopetition boundary (full co-ownership) — HEADLINE error
                    exportNotDesign: false,  // built a French course delivered abroad, no cultural design
                    accreditationSunk: false,// Brazil gap ignored + missed deadline → €740K sunk, launch slips
                    optimisticEnrolment: false, // break-even only works at top of demand range
                    underInvested: false,    // under-spent + a single weak partner → enrolment below break-even
                    deadlineMissed: false,
                    hasBrazil: false,
                    partner: ``,
                    enrolHistory: [this.START_ENROL],
                    alignHistory: [this.START_ALIGN],
                    coreHistory: [this.START_CORE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    valueprop: `export`,
                    keep: `brand`,
                    topfit: `brand`,
                    rigour: 35,
                    partner: `us_only`,
                    boundary: `coown`,
                    brazilcheck: `na`,
                    revshare: 350,
                    calendar: `impose`,
                    culture: `none`,
                    enroltarget: `58`,
                    marketing: 120,
                    accred: `rush`,
                    decision: `forcego`,
                    defence: `cost`,
                    confidence: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const ds = state.domainState;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const vp = document.getElementById(`valuepropInput`);
                const kp = document.getElementById(`keepInput`);
                const tf = document.getElementById(`topfitInput`);
                const ri = document.getElementById(`rigourInput`);
                if (vp) decisions.valueprop = vp.value;
                if (kp) decisions.keep = kp.value;
                if (tf) decisions.topfit = tf.value;
                if (ri) decisions.rigour = parseInt(ri.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const pa = document.getElementById(`partnerInput`);
                const bo = document.getElementById(`boundaryInput`);
                const bz = document.getElementById(`brazilcheckInput`);
                const rs = document.getElementById(`revshareInput`);
                if (pa) decisions.partner = pa.value;
                if (bo) decisions.boundary = bo.value;
                if (bz) decisions.brazilcheck = bz.value;
                if (rs) decisions.revshare = parseFloat(rs.value);
                if (!Number.isFinite(decisions.revshare) || decisions.revshare < 0) {
                    warn(`warn_revshare_value`); return false;
                }
                // Hard cap: total committed budget cannot exceed the €1.2M envelope.
                if (ds.budget + decisions.revshare > this.BUDGET_CAP) {
                    warn(`warn_budget_cap`); return false;
                }
            } else if (round === 3) {
                const ca = document.getElementById(`calendarInput`);
                const cu = document.getElementById(`cultureInput`);
                const et = document.getElementById(`enroltargetInput`);
                const mk = document.getElementById(`marketingInput`);
                if (ca) decisions.calendar = ca.value;
                if (cu) decisions.culture = cu.value;
                if (et) decisions.enroltarget = et.value;
                if (mk) decisions.marketing = parseFloat(mk.value);
                if (!Number.isFinite(decisions.marketing) || decisions.marketing < 0) {
                    warn(`warn_marketing_value`); return false;
                }
                if (ds.budget + decisions.marketing > this.BUDGET_CAP) {
                    warn(`warn_budget_cap`); return false;
                }
            } else if (round === 4) {
                const ac = document.getElementById(`accredInput`);
                const de = document.getElementById(`decisionInput`);
                const df = document.getElementById(`defenceInput`);
                const cf = document.getElementById(`confidenceInput`);
                if (ac) decisions.accred = ac.value;
                if (de) decisions.decision = de.value;
                if (df) decisions.defence = df.value;
                if (cf) decisions.confidence = parseInt(cf.value, 10);
                if (!Number.isFinite(decisions.confidence) || decisions.confidence < 0 || decisions.confidence > 100) {
                    warn(`warn_confidence_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let enrolDelta = 0, alignDelta = 0, coreDelta = 0, budgetDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: programme logic, the in-house core, the rubric (Common Error 3).
                switch (d.valueprop) {
                    case `designed`: alignDelta += 8; enrolDelta += 2; coachKey = `coach_r1_designed`; break;
                    case `export`: alignDelta -= 6; ds.exportNotDesign = true; coachKey = `coach_r1_export`; break;
                    case `cheapest`: alignDelta -= 3; coreDelta -= 4; coachKey = `coach_r1_cheapest`; break;
                }

                switch (d.keep) {
                    case `core`: coreDelta += 8; coachKey = (d.valueprop === `designed`) ? `coach_r1_sharp` : coachKey; break;
                    case `brand`: coreDelta -= 8; coachKey = `coach_r1_keepbrand`; break;
                    case `ops`: coreDelta -= 3; break;
                }

                switch (d.topfit) {
                    case `balanced`: alignDelta += 4; enrolDelta += 2; break;
                    case `brand`: enrolDelta += 1; coreDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_fitbrand`; break;
                    case `cost`: enrolDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_fitcost`; break;
                }

                // Modelling rigour governs how well later economics are understood.
                if (d.rigour >= 60) { enrolDelta += 1; }
                else if (d.rigour <= 25) { enrolDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r1_norigour`; }

                summaryKey = (d.valueprop === `designed` && d.keep === `core` && d.topfit === `balanced`)
                    ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Partner architecture + the coopetition boundary (Common Errors 1, 2 & 5).
                budgetDelta += d.revshare;
                ds.partner = d.partner;
                ds.hasBrazil = (d.partner === `sg_br` || d.partner === `br_only`);

                // --- Partner brand / fit / cost effects on enrolment. ---
                switch (d.partner) {
                    case `us_only`:
                        enrolDelta += 6; coreDelta -= 3;
                        ds.usShareCost = this.US_SHARE * this.BREAK_EVEN; // €405K/yr at 45 students
                        // Brand chasing if you never modelled the share against break-even.
                        if (d.rigour < 60) { ds.brandTrap = true; coachKey = `coach_r2_us_trap`; }
                        else { coachKey = `coach_r2_us_modelled`; }
                        break;
                    case `sg_only`:
                        enrolDelta += 4; alignDelta += 6;
                        // Single thin-brand partner with little spend is the under-investment failure mode.
                        coachKey = `coach_r2_sg_only`;
                        break;
                    case `sg_us`:
                        enrolDelta += 11; alignDelta += 4; coreDelta -= 1;
                        ds.usShareCost = this.US_SHARE * this.BREAK_EVEN;
                        if (d.rigour < 60) { ds.brandTrap = true; coachKey = `coach_r2_us_trap`; }
                        else { coachKey = `coach_r2_sg_us`; }
                        break;
                    case `sg_br`:
                        enrolDelta += 9; alignDelta += 5;
                        coachKey = `coach_r2_sg_br`;
                        break;
                    case `br_only`:
                        enrolDelta += 5; alignDelta += 2;
                        coachKey = `coach_r2_br_only`;
                        break;
                }

                // --- THE HEADLINE CHOICE: the coopetition boundary with Lumière. ---
                switch (d.boundary) {
                    case `deliberate`:
                        coreDelta += 14; budgetDelta -= 60; // pooling the office genuinely saves ~€60K
                        if (coachKey === `coach_default` || coachKey.indexOf(`trap`) === -1) coachKey = `coach_r2_bound_good`;
                        break;
                    case `coown`:
                        // Ceding the boundary — the run-defining error. Rival gets pricing + pipeline.
                        ds.boundaryCeded = true;
                        coreDelta -= 40; budgetDelta -= 180; // it does halve cost on paper
                        enrolDelta -= 8; // Lumière steers the strongest candidates to its own programme
                        coachKey = `coach_r2_coown`;
                        break;
                    case `exit`:
                        coreDelta += 6; budgetDelta += 90; // losing the shared office costs money
                        enrolDelta -= 4; // lose the Singapore recruitment reach
                        coachKey = `coach_r2_exit`;
                        break;
                }

                // --- Brazil accreditation handling (decision tree #4). ---
                if (ds.hasBrazil) {
                    if (d.brazilcheck === `ignore`) {
                        // The gap is left unpriced — sets up the Round-4 sunk-cost reckoning.
                        coreDelta -= 4;
                        if (coachKey === `coach_default`) coachKey = `coach_r2_brazil_ignore`;
                    } else if (d.brazilcheck === `derisk`) {
                        budgetDelta += 40; // contingency review costs money but de-risks
                        coreDelta += 4;
                        if (coachKey === `coach_default`) coachKey = `coach_r2_brazil_derisk`;
                    }
                }

                summaryKey = ds.boundaryCeded ? `sum_r2_coown`
                    : (ds.brandTrap ? `sum_r2_brand`
                    : ((d.partner === `sg_us` || d.partner === `sg_br`) && d.boundary === `deliberate` ? `sum_r2_good` : `sum_r2_weak`));
            } else if (round === 3) {
                // Curriculum, calendar reconciliation, cultural alignment, enrolment target (Common Errors 3 & 4).
                budgetDelta += d.marketing;

                switch (d.calendar) {
                    case `reconcile`: alignDelta += 9; enrolDelta += 2; budgetDelta += 30; break;
                    case `impose`: alignDelta -= 6; enrolDelta -= 2; ds.exportNotDesign = true; coachKey = `coach_r3_impose`; break;
                    case `capitulate`: alignDelta -= 2; coreDelta -= 4; coachKey = `coach_r3_capitulate`; break;
                }

                switch (d.culture) {
                    case `deep`: alignDelta += 14; enrolDelta += 3; budgetDelta += 20; break;
                    case `surface`: alignDelta += 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_surface` : coachKey; break;
                    case `none`: alignDelta -= 10; ds.exportNotDesign = true; coachKey = `coach_r3_culnone`; break;
                }

                // Enrolment target the P&L breaks even on (decision tree #5).
                ds.enrolTarget = parseInt(d.enroltarget, 10);
                if (ds.enrolTarget >= 58) {
                    ds.optimisticEnrolment = true; coachKey = `coach_r3_optimistic`;
                } else if (ds.enrolTarget <= 32) {
                    enrolDelta += 1; if (coachKey === `coach_default`) coachKey = `coach_r3_defensive`;
                } else { // 45
                    if (coachKey === `coach_default`) coachKey = `coach_r3_conservative`;
                }

                // Marketing spend lifts enrolment, with diminishing returns.
                if (d.marketing >= 200) enrolDelta += 5;
                else if (d.marketing >= 100) enrolDelta += 3;
                else if (d.marketing < 60) { enrolDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_lowmkt`; }

                summaryKey = (d.calendar === `reconcile` && d.culture === `deep` && ds.enrolTarget === 45)
                    ? `sum_r3_good`
                    : (ds.optimisticEnrolment ? `sum_r3_optimistic`
                    : (d.culture === `none` ? `sum_r3_export` : `sum_r3_weak`));
            } else if (round === 4) {
                // Accreditation, risk, go/no-go (decision tree #4; Common Error 5).
                switch (d.accred) {
                    case `complete`: coreDelta += 6; alignDelta += 2; break;
                    case `rush`: coreDelta -= 6; coachKey = `coach_r4_rush`; break;
                    case `late`: ds.deadlineMissed = true; enrolDelta -= 6; coreDelta -= 4; coachKey = `coach_r4_late`; break;
                }

                // Brazil + ignored gap + (rushed thin OR missed deadline) → the sunk-cost reckoning.
                if (ds.hasBrazil && d.brazilcheck !== `derisk` && (d.accred === `late` || d.accred === `rush`)) {
                    ds.accreditationSunk = true;
                    enrolDelta -= 12;
                    coachKey = `coach_r4_brazilsunk`;
                }

                switch (d.decision) {
                    case `conditional`: coreDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r4_conditional`; break;
                    case `go`: if (coachKey === `coach_default`) coachKey = `coach_r4_go`; break;
                    case `forcego`: coreDelta -= 4; coachKey = `coach_r4_forcego`; break;
                }

                switch (d.defence) {
                    case `own`: coreDelta += 8; if (d.decision !== `forcego` && coachKey === `coach_default`) coachKey = `coach_r4_own`; break;
                    case `brand`: coreDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r4_defbrand`; break;
                    case `cost`: coreDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r4_defcost`; break;
                }

                if (d.confidence >= 60 && ds.enrolTarget <= 45) coreDelta += 2;
                else if (d.confidence >= 60 && ds.optimisticEnrolment) { coreDelta -= 3; } // false confidence

                summaryKey = (d.accred === `complete` && d.decision !== `forcego` && d.defence === `own`)
                    ? `sum_r4_good`
                    : (ds.accreditationSunk ? `sum_r4_sunk` : `sum_r4_weak`);
            }

            // ---- Apply deltas (clamped). ----
            ds.budget = Math.max(0, Math.min(this.BUDGET_CAP + 600, Math.round(ds.budget + budgetDelta)));
            ds.enrol = Math.max(0, Math.min(this.ENROL_CEIL + 5, Math.round(ds.enrol + enrolDelta)));
            ds.align = Math.max(0, Math.min(100, Math.round(ds.align + alignDelta)));
            ds.core = Math.max(0, Math.min(100, Math.round(ds.core + coreDelta)));

            // ---- Cultural alignment GATES enrolment: an export programme bleeds completion/demand. ----
            if (ds.align < 45) {
                ds.enrol = Math.min(ds.enrol, this.BREAK_EVEN - 6); // export trap caps enrolment below break-even
            }
            // ---- Ceding the boundary CAPS enrolment: the rival is steering your candidates away. ----
            if (ds.boundaryCeded) {
                ds.enrol = Math.min(ds.enrol, this.BREAK_EVEN - 2);
            }
            // ---- Under-investment failure mode: single thin-brand partner + low total spend. ----
            if (ds.partner === `sg_only` && round >= 3 && ds.budget < 700) {
                ds.underInvested = true;
                ds.enrol = Math.min(ds.enrol, 33);
            }
            // ---- Accreditation rejection sinks the launch: enrolment for this cohort collapses. ----
            if (ds.accreditationSunk) {
                ds.enrol = Math.min(ds.enrol, 28);
            }

            ds.enrolHistory.push(ds.enrol);
            ds.alignHistory.push(ds.align);
            ds.coreHistory.push(ds.core);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            const cps = this._costPerStudent(ds);

            // v1.1.0: persist composite score + grade to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore -> performance.overallScore;
            // express_extractHistory reads it per period). Scoring UNCHANGED (faithful _composite copy).
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                budget: ds.budget,
                budgetDelta: Math.round(budgetDelta),
                enrol: ds.enrol,
                enrolDelta: Math.round(enrolDelta),
                align: ds.align,
                alignDelta: Math.round(alignDelta),
                core: ds.core,
                coreDelta: Math.round(coreDelta),
                cps: cps,
                boundaryCeded: ds.boundaryCeded,
                brandTrap: ds.brandTrap,
                accreditationSunk: ds.accreditationSunk,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        // Cost per student: amortised launch spend + (US revenue share, if any) per projected student.
        _costPerStudent(ds) {
            const students = Math.max(1, ds.enrol);
            // €K per student: launch budget spread over the cohort + the per-student US share.
            const perStudent = (ds.budget / students) + (ds.usShareCost > 0 ? this.US_SHARE : 0);
            return Math.round(perStudent * 1000); // back to €
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`budgetDisplay`, `domainState.budget`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.crossborder-card-budget`);
                if (card) card.classList.toggle(`crossborder-budget-over`, n > self.BUDGET_CAP);
                return self._fmtMoneyK(n);
            });

            uiManager.bind(`enrolDisplay`, `domainState.enrol`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.crossborder-card-enrol`);
                if (card) {
                    card.classList.toggle(`crossborder-enrol-good`, n >= self.BREAK_EVEN);
                    card.classList.toggle(`crossborder-enrol-bad`, n < self.BREAK_EVEN);
                }
                return `${n}`;
            });

            uiManager.bind(`alignDisplay`, `domainState.align`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`coreDisplay`, `domainState.core`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.crossborder-card-core`);
                if (card) card.classList.toggle(`crossborder-core-bad`, n < 50);
                return `${n}`;
            });

            uiManager.bind(`cpsDisplay`, `domainState.enrol`, () => {
                const ds = window.mySimulation.state.domainState;
                const cps = self._costPerStudent(ds);
                const bar = document.querySelector(`.crossborder-cps-bar`);
                if (bar) {
                    // Break-even reference: €1.2M / 45 = €26,667 per student.
                    bar.classList.toggle(`crossborder-cps-good`, cps <= 26667);
                    bar.classList.toggle(`crossborder-cps-bad`, cps > 40000);
                }
                if (ds.budget <= 0) return window.mySimulation.t(`cps_pending`);
                return self._fmtMoneyEuro(cps);
            });

            // Rigour slider readout.
            const ri = document.getElementById(`rigourInput`);
            const riReadout = document.getElementById(`rigourReadout`);
            if (ri && riReadout) {
                riReadout.textContent = ri.value;
                ri.addEventListener(`input`, function() { riReadout.textContent = ri.value; });
            }
        }

        _fmtMoneyK(n) {
            // €K with thousands grouping, e.g. €350K, €1,200K.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sep = lang === `es` ? `.` : `,`;
            const s = String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g, sep);
            return `€${s}K`;
        }

        _fmtMoneyEuro(n) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sep = lang === `es` ? `.` : `,`;
            const s = String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, sep);
            return `€${s}`;
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, en) => (t ? t(k) : en);
            return {
                crossborderChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_enrol`, `Projected enrolment (students)`),
                                data: [],
                                borderColor: `#1f8a76`,
                                backgroundColor: `rgba(31,138,118,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f8a76`,
                                yAxisID: `yEnrol`
                            },
                            {
                                label: L(`chart_ds_align`, `Cultural alignment (0–100)`),
                                data: [],
                                borderColor: `#d99020`,
                                backgroundColor: `rgba(217,144,32,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#d99020`,
                                yAxisID: `yScore`
                            },
                            {
                                label: L(`chart_ds_core`, `Competitive core (0–100)`),
                                data: [],
                                borderColor: `#7d5fc0`,
                                backgroundColor: `rgba(125,95,192,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7d5fc0`,
                                yAxisID: `yScore`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#45586a`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            yEnrol: {
                                beginAtZero: true, max: 65, position: `left`,
                                ticks: { color: `#1f8a76` }, grid: { color: `rgba(28,37,48,0.06)` },
                                title: { display: true, text: L(`chart_axis_students`, `Students (break-even 45)`), color: `#1f8a76` }
                            },
                            yScore: {
                                beginAtZero: true, max: 100, position: `right`,
                                ticks: { color: `#76889a` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: L(`chart_axis_score`, `Score 0–100`), color: `#76889a` }
                            },
                            x: {
                                ticks: { color: `#76889a` }, grid: { color: `rgba(28,37,48,0.04)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#76889a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.enrolHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                crossborderChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.enrolHistory },
                        { data: ds.alignHistory },
                        { data: ds.coreHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // 0-100 composite - FAITHFUL copy of v1.0.0 getPerformanceSummary (incl. sticky-flag caps).
            const enrol = Math.round(ds.enrol);
            const align = Math.round(ds.align);
            const core = Math.round(ds.core);
            const budget = Math.round(ds.budget);
            const overBudget = budget > this.BUDGET_CAP;
            const enrolScore = Math.max(0, Math.min(100, (enrol / this.BREAK_EVEN) * 80));
            let composite = Math.round(enrolScore * 0.34 + align * 0.26 + core * 0.30 + (overBudget ? 0 : 10));
            const breaksEven = enrol >= this.BREAK_EVEN && !ds.optimisticEnrolment;
            if (ds.boundaryCeded) composite = Math.min(composite, 52);
            if (ds.brandTrap) composite = Math.min(composite, breaksEven ? 70 : 55);
            if (ds.exportNotDesign && align < 50) composite = Math.min(composite, 50);
            if (ds.accreditationSunk) composite = Math.min(composite, 40);
            if (ds.optimisticEnrolment) composite = Math.min(composite, 60);
            if (ds.underInvested) composite = Math.min(composite, 48);
            return composite;
        }

        _verdictKey(ds, composite) {
            // Verdict tier -> i18n key. Pattern + thresholds IDENTICAL to v1.0.0 (labels now localized).
            const enrol = Math.round(ds.enrol);
            const align = Math.round(ds.align);
            const core = Math.round(ds.core);
            const budget = Math.round(ds.budget);
            const overBudget = budget > this.BUDGET_CAP;
            const fundable = !overBudget;
            const breaksEven = enrol >= this.BREAK_EVEN && !ds.optimisticEnrolment;
            const aligned = align >= 60;
            const coreProtected = core >= 60 && !ds.boundaryCeded;
            const accredited = !ds.accreditationSunk && !ds.deadlineMissed;
            let pattern = `mixed`;
            if (ds.boundaryCeded) pattern = `boundary_ceded`;
            else if (ds.accreditationSunk) pattern = `accreditation_sunk`;
            else if (ds.brandTrap) pattern = `brand_trap`;
            else if (ds.exportNotDesign && !aligned) pattern = `export`;
            else if (ds.underInvested) pattern = `under_invested`;
            else if (ds.optimisticEnrolment) pattern = `optimistic`;
            else if (fundable && breaksEven && aligned && coreProtected && accredited) pattern = `launch_ready`;
            if (pattern === `launch_ready` && composite >= 75) return `verdict_approved`;
            if (fundable && breaksEven && coreProtected && accredited) return `verdict_viable`;
            if (pattern === `boundary_ceded`) return `verdict_boundary`;
            if (pattern === `accreditation_sunk`) return `verdict_accreditation`;
            if (pattern === `brand_trap`) return `verdict_brand`;
            if (pattern === `export`) return `verdict_export`;
            if (pattern === `under_invested`) return `verdict_underinvested`;
            if (composite >= 58) return `verdict_mixed`;
            return `verdict_fails`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const enrol = Math.round(ds.enrol);
            const align = Math.round(ds.align);
            const core = Math.round(ds.core);
            const budget = Math.round(ds.budget);
            const cps = this._costPerStudent(ds);
            const overBudget = budget > this.BUDGET_CAP;

            // Composite, then GATE it with the sticky run-defining flags.
            const enrolScore = Math.max(0, Math.min(100, (enrol / this.BREAK_EVEN) * 80));
            let composite = Math.round(enrolScore * 0.34 + align * 0.26 + core * 0.30 + (overBudget ? 0 : 10));

            const fundable = !overBudget;
            const breaksEven = enrol >= this.BREAK_EVEN && !ds.optimisticEnrolment;
            const aligned = align >= 60;
            const coreProtected = core >= 60 && !ds.boundaryCeded;
            const accredited = !ds.accreditationSunk && !ds.deadlineMissed;

            // The HEADLINE anti-pattern (ceding the boundary) GATES the top verdict
            // and caps the composite no matter how well other rounds were played.
            if (ds.boundaryCeded) composite = Math.min(composite, 52);
            // Brand trap = prestige bought WITHOUT modelling its €9,000/student share
            // (the flag only fires when rigour < 60). That unmodelled-prestige error
            // gates the top verdict on its own, even if enrolment happens to clear 45 —
            // a modelled-prestige run never sets the flag, so it is unaffected.
            if (ds.brandTrap) composite = Math.min(composite, breaksEven ? 70 : 55);
            if (ds.exportNotDesign && align < 50) composite = Math.min(composite, 50);
            if (ds.accreditationSunk) composite = Math.min(composite, 40);
            if (ds.optimisticEnrolment) composite = Math.min(composite, 60);
            if (ds.underInvested) composite = Math.min(composite, 48);

            let pattern = `mixed`;
            if (ds.boundaryCeded) pattern = `boundary_ceded`;
            else if (ds.accreditationSunk) pattern = `accreditation_sunk`;
            else if (ds.brandTrap) pattern = `brand_trap`;
            else if (ds.exportNotDesign && !aligned) pattern = `export`;
            else if (ds.underInvested) pattern = `under_invested`;
            else if (ds.optimisticEnrolment) pattern = `optimistic`;
            else if (fundable && breaksEven && aligned && coreProtected && accredited) pattern = `launch_ready`;

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            const insights = [];
            if (pattern === `launch_ready`) insights.push(window.mySimulation.t(`insight_launch_ready`));
            else if (pattern === `boundary_ceded`) insights.push(window.mySimulation.t(`insight_boundary`));
            else if (pattern === `accreditation_sunk`) insights.push(window.mySimulation.t(`insight_accreditation`));
            else if (pattern === `brand_trap`) insights.push(window.mySimulation.t(`insight_brand`));
            else if (pattern === `export`) insights.push(window.mySimulation.t(`insight_export`));
            else if (pattern === `under_invested`) insights.push(window.mySimulation.t(`insight_underinvest`));
            else if (pattern === `optimistic`) insights.push(window.mySimulation.t(`insight_optimistic`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (!breaksEven && enrol < this.BREAK_EVEN) insights.push(window.mySimulation.t(`insight_belowbe`));
            if (!aligned) insights.push(window.mySimulation.t(`insight_align_low`));
            if (!coreProtected && !ds.boundaryCeded) insights.push(window.mySimulation.t(`insight_core_low`));
            if (cps > 40000) insights.push(window.mySimulation.t(`insight_cps_high`));

            return {
                enrol: enrol,
                align: align,
                core: core,
                budget: budget,
                cps: cps,
                fundable: fundable,
                breaksEven: breaksEven,
                aligned: aligned,
                coreProtected: coreProtected,
                accredited: accredited,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const enrol = Math.round(Number(s.enrol || 0));
            const align = Math.round(Number(s.align || 0));
            const core = Math.round(Number(s.core || 0));
            const budget = this._fmtMoneyK(Math.round(Number(s.budget || 0)));
            const cps = this._fmtMoneyEuro(Math.round(Number(s.cps || 0)));
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const approved = s.verdictKey === 'verdict_approved';
            const badgeCls = approved ? 'cbp-cm-yes' : (score >= 62 ? 'cbp-cm-mid' : 'cbp-cm-no');
            const metric = (val, lab) => '<div class="cbp-cm-metric"><span class="cbp-cm-mv">' + val + '</span><span class="cbp-cm-ml">' + lab + '</span></div>';
            const metrics = metric(enrol, T('cm_m_enrol'))
                + metric(align, T('cm_m_align'))
                + metric(core, T('cm_m_core'))
                + metric(budget, T('cm_m_budget'))
                + metric(cps, T('cm_m_cps'));
            return ''
                + '<div class="cbp-completion">'
                +   '<div class="cbp-cm-head">'
                +     '<div class="cbp-cm-score">' + score + '<span class="cbp-cm-score-max">/100</span></div>'
                +     '<div class="cbp-cm-grade">' + verdict + ' <span class="cbp-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="cbp-cm-metrics">' + metrics + '</div>'
                +   '<div class="cbp-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="cbp-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.boundaryCeded) return window.mySimulation.t(`hint_boundary`);
            if (ds.accreditationSunk) return window.mySimulation.t(`hint_accreditation`);
            if (ds.budget > this.BUDGET_CAP) return window.mySimulation.t(`hint_overbudget`);
            if (ds.brandTrap && ds.enrol < this.BREAK_EVEN) return window.mySimulation.t(`hint_brand`);
            if (ds.align < 45 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_align`);
            if (ds.optimisticEnrolment) return window.mySimulation.t(`hint_optimistic`);
            if (ds.enrol >= this.BREAK_EVEN && ds.align >= 60 && ds.core >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.enrol`, label: `Enrolment`, i18nKey: `col_enrol`, formatter: (v) => `${Math.round(v)}/${self.BREAK_EVEN}` },
                { key: `results.align`, label: `Alignment`, i18nKey: `col_align`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.core`, label: `Core`, i18nKey: `col_core`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.budget`, label: `Budget`, i18nKey: `col_budget`, formatter: (v) => self._fmtMoneyK(Math.round(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

